import{_ as a,o as l,c as o,a0 as n}from"./chunks/framework.DqMqoJl9.js";const u=JSON.parse('{"title":"基本形状","description":"","frontmatter":{},"headers":[],"relativePath":"svg/4-basic-shapes.md","filePath":"svg/4-basic-shapes.md","lastUpdated":1791426062000}'),e={name:"svg/4-basic-shapes.md"};function p(t,s,c,r,i,d){return l(),o("div",null,[...s[0]||(s[0]=[n(`<h1 id="基本形状" tabindex="-1">基本形状 <a class="header-anchor" href="#基本形状" aria-label="Permalink to &quot;基本形状&quot;">​</a></h1><h2 id="_1-矩形" tabindex="-1">1 矩形 <a class="header-anchor" href="#_1-矩形" aria-label="Permalink to &quot;1 矩形&quot;">​</a></h2><div class="language-xml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">rect</span><span style="color:#6F42C1;"> x</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;10&quot;</span><span style="color:#6F42C1;"> y</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;10&quot;</span><span style="color:#6F42C1;"> width</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;30&quot;</span><span style="color:#6F42C1;"> height</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;30&quot;</span><span style="color:#24292E;">/&gt;</span></span>
<span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">rect</span><span style="color:#6F42C1;"> x</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;60&quot;</span><span style="color:#6F42C1;"> y</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;10&quot;</span><span style="color:#6F42C1;"> rx</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;10&quot;</span><span style="color:#6F42C1;"> ry</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;10&quot;</span><span style="color:#6F42C1;"> width</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;30&quot;</span><span style="color:#6F42C1;"> height</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;30&quot;</span><span style="color:#24292E;">/&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ul><li><code>x</code> 矩形左上角的 x 位置</li><li><code>y</code> 矩形左上角的 y 位置</li><li><code>width</code> 矩形的宽度</li><li><code>height</code> 矩形的高度</li><li><code>rx</code> 圆角的 x 方位的半径</li><li><code>ry</code> 圆角的 y 方位的半径</li></ul><h2 id="_2-圆形" tabindex="-1">2 圆形 <a class="header-anchor" href="#_2-圆形" aria-label="Permalink to &quot;2 圆形&quot;">​</a></h2><p>只有 3 个属性用来设置圆形</p><div class="language-xml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">circle</span><span style="color:#6F42C1;"> cx</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;25&quot;</span><span style="color:#6F42C1;"> cy</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;75&quot;</span><span style="color:#6F42C1;"> r</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;20&quot;</span><span style="color:#24292E;">/&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>r</code> 圆的半径</li><li><code>cx</code> 圆心的 x 位置</li><li><code>cy</code> 圆心的 y 位置</li></ul><h2 id="_3-椭圆" tabindex="-1">3 椭圆 <a class="header-anchor" href="#_3-椭圆" aria-label="Permalink to &quot;3 椭圆&quot;">​</a></h2><p>ellipse 是 circle 元素更通用的形式，你可以分别缩放圆的 x 半径和 y 半径（通常数学家称之为长轴半径和短轴半径）</p><div class="language-xml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">ellipse</span><span style="color:#6F42C1;"> cx</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;75&quot;</span><span style="color:#6F42C1;"> cy</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;75&quot;</span><span style="color:#6F42C1;"> rx</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;20&quot;</span><span style="color:#6F42C1;"> ry</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;5&quot;</span><span style="color:#24292E;">/&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>rx</code> 椭圆的 x 半径</li><li><code>ry</code> 椭圆的 y 半径</li><li><code>cx</code> 椭圆中心的 x 位置</li><li><code>cy</code> 椭圆中心的 y 位置</li></ul><h2 id="_4-线条" tabindex="-1">4 线条 <a class="header-anchor" href="#_4-线条" aria-label="Permalink to &quot;4 线条&quot;">​</a></h2><p>line 绘制直线。它取两个点的位置作为属性，指定这条线的起点和终点位置。</p><div class="language-xml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">line</span><span style="color:#6F42C1;"> x1</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;10&quot;</span><span style="color:#6F42C1;"> x2</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;50&quot;</span><span style="color:#6F42C1;"> y1</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;110&quot;</span><span style="color:#6F42C1;"> y2</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;150&quot;</span><span style="color:#6F42C1;"> stroke</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;black&quot;</span><span style="color:#6F42C1;"> stroke-width</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;5&quot;</span><span style="color:#24292E;">/&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>x1</code> 起点的 x 位置</li><li><code>y1</code> 起点的 y 位置</li><li><code>x2</code> 终点的 x 位置</li><li><code>y2</code> 终点的 y 位置</li></ul><h2 id="_5-折线" tabindex="-1">5 折线 <a class="header-anchor" href="#_5-折线" aria-label="Permalink to &quot;5 折线&quot;">​</a></h2><p>polyline 是一组连接在一起的直线。因为它可以有很多的点，折线的的所有点位置都放在一个 points 属性中：</p><div class="language-xml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">polyline</span><span style="color:#6F42C1;"> points</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;60, 110 65, 120 70, 115 75, 130 80, 125 85, 140 90, 135 95, 150 100, 145&quot;</span><span style="color:#24292E;">/&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>points</code> 点集数列。每个数字用空白、逗号、终止命令符或者换行符分隔开。每个点必须包含 2 个数字，一个是 x 坐标，一个是 y 坐标。所以点列表 (0,0), (1,1) 和 (2,2) 可以写成这样：“0 0, 1 1, 2 2”。</li></ul><h2 id="_6-多边形" tabindex="-1">6 多边形 <a class="header-anchor" href="#_6-多边形" aria-label="Permalink to &quot;6 多边形&quot;">​</a></h2><p>polygon 和折线很像，它们都是由连接一组点集的直线构成。不同的是，polygon 的路径在最后一个点处自动回到第一个点。需要注意的是，矩形也是一种多边形，如果需要更多灵活性的话，你也可以用多边形创建一个矩形</p><div class="language-xml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">polygon</span><span style="color:#6F42C1;"> points</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;50, 160 55, 180 70, 180 60, 190 65, 205 50, 195 35, 205 40, 190 30, 180 45, 180&quot;</span><span style="color:#24292E;">/&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>points</code> 点集数列。每个数字用空白符、逗号、终止命令或者换行符分隔开。每个点必须包含 2 个数字，一个是 x 坐标，一个是 y 坐标。所以点列表 (0,0), (1,1) 和 (2,2) 可以写成这样：“0 0, 1 1, 2 2”。路径绘制完后闭合图形，所以最终的直线将从位置 (2,2) 连接到位置 (0,0)</li></ul><h2 id="_7-路径" tabindex="-1">7 路径 <a class="header-anchor" href="#_7-路径" aria-label="Permalink to &quot;7 路径&quot;">​</a></h2><p>path 可能是 SVG 中最常见的形状。你可以用 path 元素绘制矩形（直角矩形或者圆角矩形）、圆形、椭圆、折线形、多边形，以及一些其他的形状，例如贝塞尔曲线、2 次曲线等曲线。因为 path 很强大也很复杂，所以会在下一章进行详细介绍。这里只介绍一个定义路径形状的属性。</p><div class="language-xml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">path</span><span style="color:#6F42C1;"> d</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;M20,230 Q40,205 50,230 T90,230&quot;</span><span style="color:#6F42C1;"> fill</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;none&quot;</span><span style="color:#6F42C1;"> stroke</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;blue&quot;</span><span style="color:#6F42C1;"> stroke-width</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;5&quot;</span><span style="color:#24292E;">/&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>d</code> 一个点集数列以及其他关于如何绘制路径的信息</li></ul>`,28)])])}const h=a(e,[["render",p]]);export{u as __pageData,h as default};
